-- Sendro Instagram / SaaS database Step 5: isolated social channel messages.
-- MANUAL EXECUTION ONLY. Staging and production share one live PostgreSQL DB.
-- First verify backup, expected tenant, prior empty tables and no preexisting
-- sendro_channel_messages. Does not modify legacy WhatsApp tables or endpoints.
--
-- This migration creates ONE EMPTY TABLE, with tenant-safe foreign keys.
-- Do not populate it or enable Instagram webhook subscription yet.

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE TABLE public.sendro_channel_messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tenant_id BIGINT NOT NULL,
    channel_account_id BIGINT NOT NULL,
    conversation_id BIGINT NOT NULL,
    provider_message_id VARCHAR(255),
    direction VARCHAR(8) NOT NULL,
    message_type VARCHAR(24) NOT NULL DEFAULT 'text',
    content TEXT,
    media_json JSONB,
    provider_timestamp TIMESTAMPTZ,
    delivery_status VARCHAR(24),
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    sent_by_user_id INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_sendro_channel_messages_conversation_scope
        FOREIGN KEY (conversation_id, tenant_id, channel_account_id)
        REFERENCES public.sendro_channel_conversations
            (id, tenant_id, channel_account_id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_sendro_channel_messages_sender_member
        FOREIGN KEY (tenant_id, sent_by_user_id)
        REFERENCES public.sendro_tenant_users(tenant_id, user_id)
        ON DELETE RESTRICT,

    CONSTRAINT uq_sendro_channel_messages_provider
        UNIQUE (channel_account_id, provider_message_id),

    CONSTRAINT ck_sendro_channel_messages_direction
        CHECK (direction IN ('inbound', 'outbound')),

    CONSTRAINT ck_sendro_channel_messages_inbound_mid
        CHECK (direction <> 'inbound' OR provider_message_id IS NOT NULL),

    CONSTRAINT ck_sendro_channel_messages_body
        CHECK (content IS NOT NULL OR media_json IS NOT NULL),

    CONSTRAINT ck_sendro_channel_messages_delivery_status
        CHECK (delivery_status IS NULL OR delivery_status IN
            ('queued', 'sent', 'delivered', 'read', 'failed'))
);

CREATE INDEX idx_sendro_channel_messages_conversation_id_desc
    ON public.sendro_channel_messages (conversation_id, id DESC);

CREATE INDEX idx_sendro_channel_messages_tenant_created_desc
    ON public.sendro_channel_messages (tenant_id, created_at DESC, id DESC);

COMMIT;

-- Expected postflight: exactly 15 columns; zero rows; two foreign keys.
-- Neither Instagram access tokens nor app secrets belong in this table.
